title:
type ToOptions<
  TRouteTree extends AnyRoute = AnyRoute,
  TFrom extends RoutePaths<TRouteTree> | string = string,
  TTo extends string = '',
> = {
  // `from`은 선택적 라우트 ID 또는 경로예요. 제공하지 않으면 절대 경로만 자동완성되고 타입 안전해요. 편의를 위해 현재 렌더링 중인 출발 라우트의 route.fullPath를 제공하는 게 일반적이에요. 출발 라우트를 모른다면 비워두고 절대 경로나 안전하지 않은 상대 경로로 작업하세요.
  from?: string
  // `to`는 절대 라우트 경로이거나 `from` 옵션에서 유효한 라우트 경로까지의 상대 경로예요. ⚠️ `to` 옵션에 path params, hash, search params를 직접 보간하지 마세요. 대신 `params`, `search`, `hash` 옵션을 사용하세요.
  to: string
  // `params`는 `to` 옵션에 보간할 path params 객체이거나, 이전 params를 받아 새 params를 반환하는 함수예요. 최종 URL에 동적 파라미터를 보간하는 유일한 방법이에요. `from`과 `to` 라우트에 따라 path params를 전혀, 일부, 또는 전부 제공해야 할 수 있어요. TypeScript가 필요한 params가 있으면 알려줄 거예요.
  params:
    | Record<string, unknown>
    | ((prevParams: Record<string, unknown>) => Record<string, unknown>)
  // `search`는 query params 객체이거나, 이전 search를 받아 새 search를 반환하는 함수예요. `from`과 `to` 라우트에 따라 query params를 전혀, 일부, 또는 전부 제공해야 할 수 있어요. TypeScript가 필요한 search params가 있으면 알려줄 거예요.
  search:
    | Record<string, unknown>
    | ((prevSearch: Record<string, unknown>) => Record<string, unknown>)
  // `hash`는 문자열이거나, 이전 hash를 받아 새 hash를 반환하는 함수예요.
  hash?: string | ((prevHash: string) => string)
  // `state`는 state 객체이거나, 이전 state를 받아 새 state를 반환하는 함수예요. State는 history API에 저장되며 URL search params에 영구적으로 저장하고 싶지 않은 데이터를 라우트 간에 전달할 때 유용해요.
  state?:
    | Record<string, any>
    | ((prevState: Record<string, unknown>) => Record<string, unknown>)
  // `mask`는 이 네비게이션에서 브라우저에 표시되는 URL을 마스킹하는 데 사용되는 또 다른 네비게이션 객체예요.
  mask?: ToMaskOptions<TRouteTree>
}

type ToMaskOptions<TRouteTree extends AnyRoute = AnyRoute> = {
  // `from`, `to`, `params`, `search`, `hash`, `state`는 `ToOptions`와 동일하게 동작해요.
  // `mask` 자체는 `ToMaskOptions` 안에서 허용되지 않아요.
  from?: string
  to: string
  params:
    | Record<string, unknown>
    | ((prevParams: Record<string, unknown>) => Record<string, unknown>)
  search:
    | Record<string, unknown>
    | ((prevSearch: Record<string, unknown>) => Record<string, unknown>)
  hash?: string | ((prevHash: string) => string)
  state?:
    | Record<string, any>
    | ((prevState: Record<string, unknown>) => Record<string, unknown>)
  // true이면 페이지 새로고침 시 URL 마스킹이 해제돼요.
  unmaskOnReload?: boolean
}

