title:
export type NavigateOptions<
  TRouteTree extends AnyRoute = AnyRoute,
  TFrom extends RoutePaths<TRouteTree> | string = string,
  TTo extends string = '',
> = ToOptions<TRouteTree, TFrom, TTo> & {
  // `replace`는 네비게이션이 현재 히스토리 항목을 교체할지 새 항목을 추가할지 결정하는 boolean이에요.
  replace?: boolean
  // `resetScroll`은 위치가 브라우저 히스토리에 커밋된 후 스크롤 위치를 0,0으로 초기화할지 결정하는 boolean이에요.
  resetScroll?: boolean
  // `hashScrollIntoView`는 위치가 히스토리에 커밋된 후 hash와 일치하는 id가 뷰포트로 스크롤될지 결정하는 boolean 또는 객체예요.
  hashScrollIntoView?: boolean | ScrollIntoViewOptions
  // `viewTransition`은 네비게이션 시 브라우저가 document.startViewTransition()을 호출할지 여부와 방법을 결정하는 boolean 또는 함수예요.
  viewTransition?: boolean | ViewTransitionOptions
  // `ignoreBlocker`는 네비게이션이 이를 막을 수 있는 블로커를 무시할지 결정하는 boolean이에요.
  ignoreBlocker?: boolean
  // `reloadDocument`는 라우터 내부 라우트로의 네비게이션이 전통적인 SPA 네비게이션 대신 전체 페이지 로드를 트리거할지 결정하는 boolean이에요.
  reloadDocument?: boolean
  // `href`는 `to` 대신 사용할 수 있는 문자열로, 외부 대상을 가리키는 경우 등 완전히 빌드된 href로 네비게이션할 때 사용해요.
  href?: string
}

