  // true이면 현재 라우트가 `to` 라우트 경로와 정확히 일치할 때(자식 라우트 없음) 링크가 active 상태가 돼요.
  // 기본값은 `false`
  exact?: boolean
  // true이면 현재 URL hash가 `hash` prop과 일치할 때만 링크가 active 상태가 돼요.
  // 기본값은 `false`
  includeHash?: boolean
  // true이면 현재 URL search params가 `search` prop을 포함할 때만 링크가 active 상태가 돼요.
  // 기본값은 `true`
  includeSearch?: boolean
  // `includeSearch` 동작을 수정해요.
  // true이면 `search`에서 명시적으로 `undefined`인 속성이 현재 URL search params에 없어야 링크가 active 상태가 돼요.
  // 기본값은 `false`
  explicitUndefined?: boolean
}

